   if h.text(cell).startswith('MIC and MBC'):
    note='MIC and MBC in mg/L, modelled on log2 scale. Multitask supplies a species/endpoint task code; recovered CatBoost code uses native categorical task_id. Encoded classes supplies OpenAI task-description vectors. Original reported values; see text for provenance and rounding correction.'
    if table is old[51]:note+=' The full-corpus quantitative multitarget checkpoint remains unresolved.'
