 modernrows=[['Separate-endpoint decoder','Representation','Cation CV','Scaffold CV','OOD-17']]
 for model,label in [('catboost','CatBoost'),('tabpfn','TabPFN v2'),('tabfm','TabFM'),('autogluon','AutoGluon')]:
  for rep in ['v5_raw','v5_human']:
   vals=[metric(rep,'separate',s).RMSE if model=='catboost' else modern[(modern.model==model)&(modern.representation==rep)&(modern.schema==s)&(modern.task=='pooled')].RMSE.item() for s in ['cation','scaffold','full-QAC105']]
   modernrows.append([label,'Raw' if rep=='v5_raw' else 'Human-guided']+[f'{z:.3f}' for z in vals])
 direct=pd.read_csv(ROOT.parent/'revision_v16/analysis/direct_summary.csv')
 frozen=pd.read_csv(ROOT.parent/'revision_v16/analysis/ablation_metrics.csv')
 routes=[['Backbone experiment / route','Paired seeds','Cation CV','Scaffold CV','OOD-17']]
 for arm,mode,label in [('raw-molformer','frozen','Pretrained / frozen linear head'),('raw-molformer','lora','Pretrained / direct LoRA'),('raw-molformer','full','Pretrained / direct full FT'),('expert','partial','Human partial / direct prediction')]:
  a=direct[(direct.arm==arm)&(direct['mode']==mode)&(direct.task=='pooled')]
